import {mountTeam} from '/admin/team.js';
import {mountNotifications} from '/admin/notifications.js';
import {mountShopAdmin} from '/loja/admin/admin.js';
import {api,icon,esc,dateLabel,minuteLabel,durationLabel,addDays,statusLabel,brand,notify,moneyLabel,moneyCents,paymentLabels,birthdayMonths,chemicalOptions,hairProblemOptions} from '/booking/shared.js';
const root=document.getElementById('admin-root'),dialog=document.getElementById('details-dialog');
const state={view:'overview',session:null,settings:null,bookings:[],blocks:[],today:'',date:'',filter:'all',search:'',selected:null,finance:null,financeFrom:'',financeTo:'',financeOffset:0,financeSource:'all',directoryOffset:0,directoryQuery:'',birthdayMonth:null,birthdaysToday:0};
const mainViews=['overview','agenda','customers','birthdays','products','orders','finance','settings','notifications','team'];
if(mainViews.includes(location.hash.slice(1)))state.view=location.hash.slice(1);
const dayNames=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const initials=name=>name.split(' ').filter(Boolean).map(n=>n[0]).slice(0,2).join('').toUpperCase();
async function start(){try{state.session=await api('/api/session');if(recoveryToken||!state.session.admin)return renderLogin();await loadData();renderShell();}catch(error){renderError(error.message);}}
function renderError(message){root.innerHTML=`<div class="boot-state">${icon('calendar')}<p>${esc(message)}</p><button class="btn" id="retry-start">Tentar novamente</button></div>`;document.getElementById('retry-start').onclick=start;}
let setupKey='',recoveryToken='';
function readAccessFragment(){const params=new URLSearchParams(location.hash.slice(1));if(!params.has('setup')&&!params.has('recovery'))return false;setupKey=params.get('setup')||'';recoveryToken=params.get('recovery')||'';history.replaceState(null,'',location.pathname+location.search);return true;}
readAccessFragment();
window.addEventListener('hashchange',()=>{if(readAccessFragment())start();else if(mainViews.includes(location.hash.slice(1))){state.view=location.hash.slice(1);if(state.session?.admin)renderShell();}});
function renderLogin(){
 let recovery=!!recoveryToken&&!state.session.local,setup=!recovery&&!!setupKey&&!state.session.local;
 root.innerHTML=`<main class="login-layout" id="main-content"><section class="login-art"><img src="/assets/loiro-perolado.jpg" alt="" aria-hidden="true">${brand}<div><p class="label">SEU ESPAÇO DE CUIDADO</p><h1>Organize seus dias.<br><em>Valorize cada encontro.</em></h1><p>Agenda, clientes e loja do Babi Instituto em um só lugar.</p></div><span class="login-art-bottom">BABI INSTITUTO DE BELEZA • POR FABRÍCIA LEÃO</span></section><section class="login-form"><div class="login-form-inner"><div class="login-mark">${icon('shield')}</div><p class="label">ÁREA ADMINISTRATIVA</p><h2>${recovery?'Defina sua nova senha.':setup?'Defina seu acesso.':'Bem-vinda ao seu painel.'}</h2><p>${recovery?'Escolha uma nova senha de 12 a 128 caracteres e repita abaixo. Este link é temporário e pode ser usado uma única vez.':setup?'Use o e-mail autorizado e escolha uma senha com pelo menos 12 caracteres. Este acesso inicial só pode ser configurado uma vez.':'Entre para cuidar da agenda, dos produtos, dos pedidos e do financeiro do instituto.'}</p>${state.session.local?'<button class="btn" id="local-login">Acessar painel local '+icon('arrow')+'</button><div class="login-local">Acesso de desenvolvimento, disponível apenas neste computador.</div>':`<form id="admin-access-form" class="admin-access-form">${!recovery?`<label class="field">${setup?'E-mail':'Nome de acesso ou e-mail'}<input name="login" type="${setup?'email':'text'}" autocomplete="username" autocapitalize="none" spellcheck="false" required maxlength="254"></label>`:''}<label class="field">${recovery?'Nova senha':'Senha'}<input name="password" type="password" autocomplete="${setup||recovery?'new-password':'current-password'}" required minlength="12" maxlength="128"></label>${setup||recovery?'<label class="field">Repita a senha<input name="confirm" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label>':''}<p id="access-error" class="access-error" role="alert"></p><button class="btn" type="submit">${recovery?'Definir nova senha':setup?'Definir meu acesso':'Entrar no painel'} ${icon('arrow')}</button></form>`}<a class="login-back" href="/">${icon('arrow')} Voltar ao site</a></div></section></main>`;
 if(state.session.local)document.getElementById('local-login').onclick=async event=>{event.currentTarget.disabled=true;try{await api('/api/local-login',{method:'POST',body:'{}'});await start();}catch(error){notify(error.message,true);event.currentTarget.disabled=false;}};
 const form=document.getElementById('admin-access-form');
 if(form)form.onsubmit=async event=>{
  event.preventDefault();const fields=new FormData(form),button=form.querySelector('button'),error=document.getElementById('access-error');error.textContent='';
  if((setup||recovery)&&fields.get('password')!==fields.get('confirm')){error.textContent='As senhas precisam ser iguais.';return;}
  button.disabled=true;
  try{
   if(recovery){
    await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({token:recoveryToken,newPassword:fields.get('password')})});
    recoveryToken='';form.reset();state.bookings=[];state.finance=null;state.selected=null;state.view='overview';dialog.close();dialog.innerHTML='';
    state.session={admin:false,local:false,authenticated:false};renderLogin();notify('Nova senha definida. Entre no painel com ela.');return;
   }
   const credentials={login:fields.get('login'),password:fields.get('password')};
   if(setup){await api('/api/setup',{method:'POST',headers:{'x-babi-setup-key':setupKey},body:JSON.stringify({email:credentials.login,password:credentials.password})});setupKey='';setup=false;}
   await api('/api/auth/sign-in/email',{method:'POST',body:JSON.stringify(credentials)});form.reset();await start();
  }catch(failure){error.textContent=typeof failure.message==='string'&&!failure.message.startsWith('[object')?failure.message:'Não foi possível entrar. Confira o nome de acesso e a senha.';button.disabled=false;}
 };
}
async function loadData(){const settings=await api('/api/admin/settings');state.settings=settings;const config=await api('/api/config');state.today=config.today;if(!state.date)state.date=config.today;const month=state.date.slice(0,7),first=month+'-01',last=addDays(addDays(first,32).slice(0,7)+'-01',-1);const result=await api(`/api/admin/bookings?from=${addDays(first,-7)}&to=${addDays(last,7)}`);state.bookings=result.bookings;const [blocks,birthdays]=await Promise.all([api('/api/admin/blocks'),api('/api/admin/birthdays/today')]);state.blocks=blocks.blocks;state.birthdaysToday=birthdays.total;}
const moduleGroups=[
 ['Gestão',[['overview','Visão geral','O dia e os números do Instituto','grid'],['finance','Financeiro','Entradas, saídas e saldo','wallet'],['notifications','Notificações','Avisos de pedidos e agendamentos','bell'],['team','Acessos','Senhas da equipe','users']]],
 ['Atendimento',[['agenda','Agenda','Atendimentos e bloqueios','calendar'],['settings','Serviços e horários','Serviços, expediente e almoço','settings']]],
 ['Loja',[['products','Produtos','Catálogo, preços e estoque','box'],['orders','Pedidos','Acompanhe as vendas da loja','bag']]],
 ['Clientes',[['customers','Clientes','Cadastro e histórico de compras','users'],['birthdays','Aniversários','Lembre os dias especiais','calendar']]]
];
function moduleTitle(){return moduleGroups.flatMap(([,items])=>items).find(([view])=>view===state.view)?.[1]||'Painel';}
function navigateTo(view){state.view=view;history.replaceState(null,'','#'+view);state.directoryOffset=0;renderShell();window.scrollTo({top:0,behavior:'instant'});}
function mobileNavigation(){return `<nav class="mobile-dock" aria-label="Acessos principais">${[['overview','Início','grid'],['agenda','Agenda','calendar'],['products','Loja','bag'],['finance','Financeiro','wallet']].map(([view,label,symbol])=>`<button data-view="${view}" ${state.view===view||(view==='products'&&state.view==='orders')?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></button>`).join('')}<button data-open-modules aria-haspopup="dialog" aria-controls="modules-dialog" ${['customers','birthdays','settings','notifications','team'].includes(state.view)?'aria-current="page"':''}>${icon('grid')}<span>Módulos</span></button></nav><dialog class="modules-dialog" id="modules-dialog" aria-labelledby="modules-title"><header><div><p class="label">BABI INSTITUTO</p><h2 id="modules-title">Seu painel</h2></div><button class="icon-btn" data-close-modules aria-label="Fechar módulos">${icon('close')}</button></header><div class="module-groups">${moduleGroups.map(([group,items])=>`<section><h3>${group}</h3>${items.filter(([view])=>view!=='team'||state.session.owner).map(([view,label,help,symbol])=>`<button data-view="${view}" ${state.view===view?'aria-current="page"':''}><span class="module-symbol">${icon(symbol)}</span><span><strong>${label}</strong><small>${help}</small></span>${icon('chevron')}</button>`).join('')}</section>`).join('')}</div><footer><a href="/" target="_blank" rel="noopener noreferrer">Ver o site ${icon('up')}</a><a href="/loja/" target="_blank" rel="noopener noreferrer">Ver a loja ${icon('up')}</a><button data-signout>${icon('logout')} Sair do painel</button></footer></dialog>`;}
function sidebar(){return `<aside class="sidebar"><div class="sidebar-brand">${brand}</div><strong class="mobile-current-module">${moduleTitle()}</strong><button class="admin-menu-toggle" data-open-modules aria-haspopup="dialog" aria-controls="modules-dialog" aria-label="Abrir módulos do painel">${icon('grid')}</button><p class="sidebar-label">SEU INSTITUTO</p><nav class="sidebar-nav" id="system-nav" aria-label="Administração"><button data-view="overview" class="${state.view==='overview'?'active':''}">${icon('grid')} Visão geral</button><button data-view="agenda" class="${state.view==='agenda'?'active':''}">${icon('calendar')} Agenda</button><button data-view="customers" class="${state.view==='customers'?'active':''}">${icon('users')} Clientes</button><button data-view="birthdays" class="${state.view==='birthdays'?'active':''}">${icon('calendar')} Aniversários${state.birthdaysToday?'<span class="birthday-count">'+state.birthdaysToday+'</span>':''}</button><button data-view="products" class="${state.view==='products'?'active':''}">${icon('box')} Produtos</button><button data-view="orders" class="${state.view==='orders'?'active':''}">${icon('bag')} Pedidos</button><button data-view="finance" class="${state.view==='finance'?'active':''}">${icon('wallet')} Financeiro</button><button data-view="settings" class="${state.view==='settings'?'active':''}">${icon('settings')} Serviços e horários</button><button data-view="notifications" class="${state.view==='notifications'?'active':''}">${icon('bell')} Notificações</button>${state.session.owner?`<button data-view="team" class="${state.view==='team'?'active':''}">${icon('users')} Acessos</button>`:''}</nav><div class="sidebar-client"><a href="/agendar/" target="_blank" rel="noopener noreferrer">Página da cliente ${icon('up')}</a><a href="/loja/" target="_blank" rel="noopener noreferrer">Loja de produtos ${icon('up')}</a><p>Agenda e loja, em um só lugar.</p></div><div class="sidebar-bottom"><div class="admin-profile">${state.session.owner||state.session.local?'<img src="/assets/fabricia-leao.jpg" alt="">':`<span class="team-avatar" aria-hidden="true">${esc(initials(state.session.displayName||'Equipe Babi'))}</span>`}<div><strong>${esc(state.session.displayName||'Fabrícia Leão')}</strong><small>${state.session.local?'Ambiente local':state.session.owner?'Conta principal':'Equipe Babi'}</small></div></div><button class="signout" data-signout>${icon('logout')} Sair do painel</button></div></aside>`;}
function renderShell(){if(state.view==='team'&&!state.session.owner){state.view='overview';history.replaceState(null,'','#overview');}dialog.close();dialog.innerHTML='';root.innerHTML=`${sidebar()}<main class="admin-main" id="main-content"><header class="admin-topbar"><p class="label">BABI / ${state.view==='settings'?'CONFIGURAÇÕES':'ADMINISTRAÇÃO'}</p><div class="topbar-actions"><span class="live-dot">${state.settings.enabled?'Agenda online ativa':'Agenda online pausada'}</span><button class="icon-btn" id="refresh" aria-label="Atualizar agenda">${icon('refresh')}</button></div></header>${state.birthdaysToday&&['overview','agenda'].includes(state.view)?`<div class="notice birthday-alert">${icon('calendar')}<span><strong>${state.birthdaysToday===1?'Uma cliente faz aniversário hoje.':state.birthdaysToday+' clientes fazem aniversário hoje.'}</strong></span><button class="btn btn-secondary" id="open-birthdays">Ver aniversários</button></div>`:''}<div id="view-content"></div><footer class="admin-footer"><span>Agenda, clientes e loja em um só lugar.</span><span>BABI INSTITUTO DE BELEZA</span></footer></main>${mobileNavigation()}`;
root.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>navigateTo(button.dataset.view));
document.getElementById('open-birthdays')?.addEventListener('click',()=>{state.view='birthdays';state.directoryOffset=0;state.birthdayMonth=null;renderShell();});
const modules=document.getElementById('modules-dialog');
root.querySelectorAll('[data-open-modules]').forEach(button=>button.onclick=()=>modules.showModal());
modules.querySelector('[data-close-modules]').onclick=()=>modules.close();
modules.addEventListener('click',event=>{if(event.target===modules){const bounds=modules.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)modules.close();}});
document.getElementById('refresh').onclick=async()=>{try{await loadData();renderShell();notify('Agenda atualizada.');}catch(error){notify(error.message,true);}};
root.querySelectorAll('[data-signout]').forEach(button=>button.addEventListener('click',async()=>{await api(state.session.local?'/api/local-logout':'/api/auth/sign-out',{method:'POST',body:'{}'});state.bookings=[];state.finance=null;state.selected=null;dialog.close();dialog.innerHTML='';await start();}));
if(['products','orders'].includes(state.view))renderShopModule();else if(state.view==='settings')renderSettings();else if(state.view==='finance')renderFinance();else if(state.view==='notifications')mountNotifications(document.getElementById('view-content'));else if(state.view==='team')mountTeam(document.getElementById('view-content'));else if(['customers','birthdays'].includes(state.view))renderDirectory();else renderAgenda();}
function renderShopModule(){
 const area=document.getElementById('view-content');
 area.innerHTML=`<nav class="shop-module-tabs" aria-label="Gestão da loja"><button data-shop-view="products" ${state.view==='products'?'aria-current="page"':''}>${icon('box')} Produtos</button><button data-shop-view="orders" ${state.view==='orders'?'aria-current="page"':''}>${icon('bag')} Pedidos</button></nav>`+'<div class="admin-body shop-module-surface"><div id="shop-admin-main"></div><dialog class="shop-admin-dialog" id="shop-admin-dialog" aria-labelledby="dialog-title"></dialog></div>';
 area.querySelectorAll('[data-shop-view]').forEach(button=>button.onclick=()=>navigateTo(button.dataset.shopView));
 mountShopAdmin({main:document.getElementById('shop-admin-main'),dialog:document.getElementById('shop-admin-dialog'),view:state.view,embedded:true,onChange:loadData,onExpired:start});
}
function renderAgenda(){const selectedDay=state.bookings.filter(b=>b.date===state.date),nextWeek=state.bookings.filter(b=>b.date>=state.date&&b.date<=addDays(state.date,6)&&b.status==='confirmed'),unique=new Set(state.bookings.filter(b=>b.status!=='cancelled').map(b=>b.phone));
document.getElementById('view-content').innerHTML=`<div class="page-title"><div><h1>${state.view==='overview'?'Seu dia, em boas mãos.':'Cada encontro, no seu lugar.'}</h1><p>${state.view==='overview'?`Bem-vinda, ${esc((state.session.displayName||'Fabrícia').split(' ')[0])}. Aqui, cada momento tem o seu lugar.`:'Acompanhe os horários e cuide dos próximos atendimentos.'}</p></div><span class="date-pill">${icon('calendar')}${esc(dateLabel(state.today,{day:'numeric',month:'long',year:'numeric'}))}</span></div>${!state.settings.enabled?`<div class="notice">${icon('settings')}<span>A agenda online está pausada. Revise os serviços, durações e horários antes de ativar.</span><button id="open-settings">Configurar agenda ${icon('up')}</button></div>`:''}${state.view==='overview'?`<section class="welcome-banner"><div class="welcome-copy"><p class="label">TEMPO PARA O QUE IMPORTA</p><h2>Mais organização.<br><em>Mais espaço para transformar.</em></h2><p>Os horários reservados pelas clientes aparecem aqui, com confirmação automática.</p></div><div class="welcome-photo"><img src="/assets/cachos.jpg" alt="" aria-hidden="true">${icon('flower')}</div></section><section class="metrics" aria-label="Resumo da agenda"><article class="metric"><div class="metric-head">Atendimentos no dia ${icon('calendar')}</div><strong>${selectedDay.filter(b=>b.status!=='cancelled').length.toString().padStart(2,'0')}</strong><span>${esc(dateLabel(state.date))}</span></article><article class="metric"><div class="metric-head">Próximos 7 dias ${icon('check')}</div><strong>${String(nextWeek.length).padStart(2,'0')}</strong><span>Horários confirmados</span></article><article class="metric"><div class="metric-head">Clientes no período ${icon('users')}</div><strong>${String(unique.size).padStart(2,'0')}</strong><span>Na agenda carregada deste mês</span></article><article class="metric"><div class="metric-head">Cancelamentos ${icon('clock')}</div><strong>${String(state.bookings.filter(b=>b.status==='cancelled').length).padStart(2,'0')}</strong><span>Na agenda carregada deste mês</span></article></section>`:''}<section class="panel" aria-label="Agenda de atendimentos"><div class="panel-header"><div><h2>Sua agenda</h2><p>Os próximos momentos de beleza começam aqui.</p></div><a class="btn" href="/agendar/" target="_blank" rel="noopener noreferrer">${icon('plus')} Novo agendamento</a></div><div class="week-strip">${weekStrip()}</div><div class="table-toolbar"><div><h3>${esc(dateLabel(state.date,{weekday:'long',day:'numeric',month:'long'}))}</h3></div><input class="date-picker" id="agenda-date" type="date" value="${state.date}" aria-label="Escolher dia da agenda"><label class="search-field">${icon('search')}<input id="search-bookings" type="search" placeholder="Buscar cliente ou serviço" value="${esc(state.search)}" aria-label="Buscar cliente ou serviço"></label></div><div class="table-filters" role="group" aria-label="Filtrar por situação">${[['all','Todos'],['confirmed','Confirmados'],['completed','Concluídos'],['cancelled','Cancelados']].map(([value,label])=>`<button data-status="${value}" class="${state.filter===value?'active':''}" aria-pressed="${state.filter===value}">${label}</button>`).join('')}</div><div id="appointment-results"></div><div class="table-footer"><span class="live-dot">Confirmação automática</span><span>Horários no fuso de Salvador • America/Bahia</span></div></section>`;
document.getElementById('open-settings')?.addEventListener('click',()=>{state.view='settings';renderShell();});
document.getElementById('agenda-date').onchange=async event=>{if(!event.target.value)return;state.date=event.target.value;try{await loadData();renderAgenda();}catch(error){notify(error.message,true);}};
root.querySelectorAll('[data-day]').forEach(button=>button.onclick=async()=>{state.date=button.dataset.day;try{await loadData();renderAgenda();}catch(error){notify(error.message,true);}});
document.getElementById('search-bookings').oninput=event=>{state.search=event.target.value;renderRows();};
root.querySelectorAll('[data-status]').forEach(button=>button.onclick=()=>{state.filter=button.dataset.status;root.querySelectorAll('[data-status]').forEach(el=>{el.classList.toggle('active',el===button);el.setAttribute('aria-pressed',String(el===button));});renderRows();});renderRows();}
function weekStrip(){const weekday=new Date(state.date+'T12:00:00Z').getUTCDay(),monday=addDays(state.date,-((weekday+6)%7));return Array.from({length:7},(_,i)=>{const date=addDays(monday,i),has=state.bookings.some(b=>b.date===date&&b.status!=='cancelled');return `<button class="week-day ${state.date===date?'active':''} ${state.today===date?'today':''}" data-day="${date}" aria-label="${esc(dateLabel(date,{weekday:'long',day:'numeric',month:'long'}))}" aria-pressed="${state.date===date}"><span>${esc(dateLabel(date,{weekday:'short'}).replace('.',''))}</span><strong>${Number(date.slice(-2))}</strong><i class="${has?'':'empty'}"></i></button>`;}).join('');}
function renderRows(){const query=state.search.toLocaleLowerCase('pt-BR'),rows=state.bookings.filter(b=>b.date===state.date&&(state.filter==='all'||b.status===state.filter)&&[b.customer_name,b.service_name,b.phone].join(' ').toLocaleLowerCase('pt-BR').includes(query));const area=document.getElementById('appointment-results');if(!rows.length){area.innerHTML=`<div class="empty-state"><div class="empty-icon">${icon('calendar')}</div><h3>${state.search||state.filter!=='all'?'Nenhum resultado com esse filtro.':'Um novo dia, muitas possibilidades.'}</h3><p>${state.search||state.filter!=='all'?'Tente outro nome, serviço ou situação para encontrar um atendimento.':'Os agendamentos deste dia aparecerão aqui. Compartilhe a página da cliente quando sua agenda estiver pronta.'}</p><a class="btn btn-secondary" href="/agendar/" target="_blank" rel="noopener noreferrer">Ver página da cliente ${icon('up')}</a></div>`;return;}
area.innerHTML=`<div class="table-wrap"><table class="appointments-table"><thead><tr><th>Cliente</th><th>Serviço</th><th>Horário</th><th>Situação</th><th><span class="muted">Detalhes</span></th></tr></thead><tbody>${rows.map(b=>`<tr><td><div class="client-cell"><span class="initial-avatar">${esc(initials(b.customer_name))}</span><div><strong>${esc(b.customer_name)}</strong><small>${esc(b.phone)}</small></div></div></td><td class="table-service"><strong>${esc(b.service_name)}</strong><small>${durationLabel(b.duration)}</small></td><td class="time-cell"><strong>${minuteLabel(b.start_minute)}</strong><small>até ${minuteLabel(b.start_minute+b.duration)}</small></td><td><span class="status ${b.status}">${statusLabel[b.status]}</span></td><td><button class="icon-btn" data-booking="${b.id}" aria-label="Ver agendamento de ${esc(b.customer_name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;area.querySelectorAll('[data-booking]').forEach(button=>button.onclick=()=>openBooking(button.dataset.booking));}
let detailRequest=0;
async function openBooking(id){const sequence=++detailRequest;state.selected=state.bookings.find(b=>b.id===id);renderDetails();if(!dialog.open)dialog.showModal();try{const data=await api('/api/admin/bookings/'+id+'/anamnesis');if(sequence===detailRequest&&state.selected?.id===id&&dialog.open&&document.getElementById('anamnesis-body'))renderAnamnesisDetails(data.anamnesis);}catch(error){const area=document.getElementById('anamnesis-body');if(sequence===detailRequest&&area){area.textContent='Não foi possível carregar a anamnese.';const retry=document.createElement('button');retry.className='btn btn-secondary';retry.textContent='Tentar novamente';retry.onclick=()=>openBooking(id);area.append(retry);}}}
function renderAnamnesisDetails(a){const area=document.getElementById('anamnesis-body');if(!a){area.innerHTML='<p class="muted">Este agendamento não possui anamnese registrada.</p>';return;}const answers={yes:'Sim',no:'Não',unsure:'Não sabe informar',private:'Prefere conversar pessoalmente'};const choiceLabels=(values,labels)=>Array.isArray(values)?values.filter(key=>Object.hasOwn(labels,key)).map(key=>labels[key]).join(', '):'';const chemical=choiceLabels(a.chemicalTypes,chemicalOptions),problems=choiceLabels(a.hairProblemTypes,hairProblemOptions);area.innerHTML=`<dl class="intake-answers"><div><dt>Histórico de química</dt><dd>${esc(answers[a.chemicalHistory])}</dd>${chemical?'<dd>'+esc(chemical)+'</dd>':''}${a.chemicalDetails?'<dd class="intake-text">'+esc(a.chemicalDetails)+'</dd>':''}</div><div><dt>${a.hairProblems?'Problemas capilares':'Alergias ou reações a produtos'}</dt><dd>${esc(answers[a.hairProblems??a.allergies])}</dd>${problems?'<dd>'+esc(problems)+'</dd>':''}${a.allergyDetails?'<dd class="intake-text">'+esc(a.allergyDetails)+'</dd>':''}</div>${a.birthday?'<div><dt>Nascimento</dt><dd>'+esc(birthdayLabel(a.birthday.day,a.birthday.month))+'</dd></div>':''}<div><dt>Cuidados e observações</dt><dd class="intake-text">${esc(a.hairCare||'Nenhuma observação informada.')}</dd></div></dl><p class="intake-consent-note">Uso autorizado pela cliente em ${esc(new Date(a.consentedAt).toLocaleString('pt-BR',{timeZone:'America/Bahia'}))}. Respostas privadas do atendimento.</p>`;}
function renderDetails(){const b=state.selected;dialog.innerHTML=`<div class="dialog-top"><div><h2 id="dialog-title">Seu próximo encontro</h2><p>AGENDAMENTO BABI-${b.id.slice(0,8).toUpperCase()}</p></div><button class="icon-btn" id="close-dialog" aria-label="Fechar detalhes">${icon('close')}</button></div><div class="dialog-body"><div class="dialog-client"><span class="initial-avatar">${esc(initials(b.customer_name))}</span><div><h3>${esc(b.customer_name)}</h3><a href="tel:+${b.phone.length<=11?"55":""}${esc(b.phone)}">${esc(b.phone)}</a></div></div><dl class="detail-grid"><div><dt>Serviço</dt><dd>${esc(b.service_name)}</dd></div><div><dt>Situação</dt><dd><span class="status ${b.status}">${statusLabel[b.status]}</span></dd></div><div><dt>Data</dt><dd>${esc(dateLabel(b.date,{day:'numeric',month:'long',year:'numeric'}))}</dd></div><div><dt>Horário</dt><dd>${minuteLabel(b.start_minute)} às ${minuteLabel(b.start_minute+b.duration)} · ${durationLabel(b.duration)}</dd></div></dl>${b.notes?`<div class="dialog-notes">${esc(b.notes)}</div>`:''}<section class="anamnesis-panel"><h3>Anamnese capilar</h3><div id="anamnesis-body"><p class="muted">Consultando respostas...</p></div></section>${b.status==='confirmed'?`<div class="dialog-actions"><button class="btn btn-secondary" id="reschedule">Reagendar</button><button class="btn btn-success" id="complete-booking">${icon('check')} Concluir</button><button class="btn btn-danger" id="cancel-booking">Cancelar</button></div><div id="booking-extra"></div>`:''}</div>`;
document.getElementById('close-dialog').onclick=()=>dialog.close();document.getElementById('complete-booking')?.addEventListener('click',renderCompletion);document.getElementById('cancel-booking')?.addEventListener('click',()=>{document.getElementById('booking-extra').innerHTML=`<div class="reschedule-form"><p>Cancelar o atendimento de ${esc(b.customer_name)}? O horário ficará disponível novamente para outras clientes.</p><button class="btn btn-danger" id="confirm-cancel">Sim, cancelar atendimento</button></div>`;document.getElementById('confirm-cancel').onclick=()=>mutateBooking({status:'cancelled'});});document.getElementById('reschedule')?.addEventListener('click',renderReschedule);}
async function mutateBooking(data){const buttons=dialog.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await api(`/api/admin/bookings/${state.selected.id}`,{method:'PATCH',body:JSON.stringify({...data,revision:state.selected.revision})});dialog.close();await loadData();renderShell();notify(data.status==='cancelled'?'Atendimento cancelado. O horário foi liberado.':data.status==='completed'?'Atendimento concluído e entrada registrada no financeiro.':'Atendimento reagendado.');}catch(error){notify(error.message,true);buttons.forEach(b=>b.disabled=false);}}
function renderReschedule(){const b=state.selected;document.getElementById('booking-extra').innerHTML=`<form id="reschedule-form" class="reschedule-form"><p>Escolha uma nova data e consulte os horários. A duração original do atendimento será preservada.</p><div class="form-two"><label class="field">Nova data<input type="date" id="new-date" value="${b.date}" min="${state.today}" required></label><label class="field">Novo horário<select id="new-time" required><option value="">Escolha uma data</option></select></label></div><button class="btn" id="save-reschedule" disabled>Salvar novo horário ${icon('check')}</button><p id="reschedule-message"></p></form>`;
const dateInput=document.getElementById('new-date'),select=document.getElementById('new-time'),save=document.getElementById('save-reschedule');async function fetchSlots(){select.innerHTML='<option value="">Consultando...</option>';save.disabled=true;try{const data=await api(`/api/admin/availability?date=${dateInput.value}&booking=${b.id}`);select.innerHTML='<option value="">Escolher horário</option>'+data.slots.map(t=>`<option value="${t}">${t}</option>`).join('');document.getElementById('reschedule-message').textContent=data.slots.length?'':data.reason;}catch(error){document.getElementById('reschedule-message').textContent=error.message;}}dateInput.onchange=fetchSlots;select.onchange=()=>save.disabled=!select.value;document.getElementById('reschedule-form').onsubmit=event=>{event.preventDefault();mutateBooking({date:dateInput.value,time:select.value});};fetchSlots();}
dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
const moneyInputValue=cents=>cents==null?'':(cents/100).toFixed(2).replace('.',',');
function serviceSettingRow(service,index,isDraft=false){const key=esc(service.id);return `<div class="service-setting" data-service-id="${key}"><div class="service-setting-title"><input type="checkbox" name="service-active-${key}" ${service.active?'checked':''} aria-label="Disponibilizar ${esc(service.name||'novo serviço')} para agendamento"><input type="text" name="service-name-${key}" value="${esc(service.name)}" minlength="3" maxlength="70" required aria-label="Nome do serviço ${index+1}" placeholder="Nome do serviço"></div><div class="service-setting-meta"><label class="field service-description-field">Descrição<input name="service-description-${key}" value="${esc(service.description)}" maxlength="180"></label><label class="field">Duração (min)<input type="number" name="service-duration-${key}" value="${service.duration}" min="15" max="480" step="15" required placeholder="Ex.: 60"></label><label class="field">Valor padrão (R$)<input name="service-price-${key}" inputmode="decimal" maxlength="12" pattern="[0-9]+([.,][0-9]{1,2})?" title="Use um valor positivo ou zero, com até duas casas decimais." value="${moneyInputValue(service.priceCents)}" placeholder="Não definido"><small>Opcional. Zero para cortesia.</small></label></div>${isDraft?'<button type="button" class="cancel-service-draft">Cancelar novo serviço</button>':''}</div>`;}
function daySettingRow(day){const name=dayNames[day.day];return `<div class="weekly-day"><div class="day-setting"><label class="checkbox-label"><input type="checkbox" name="day-enabled-${day.day}" ${day.enabled?'checked':''}>${name}</label><input type="time" step="900" name="day-open-${day.day}" value="${day.open}" required aria-label="Abertura de ${name}"><span>–</span><input type="time" step="900" name="day-close-${day.day}" value="${day.close}" required aria-label="Fechamento de ${name}"></div><div class="lunch-setting"><label class="checkbox-label"><input type="checkbox" name="day-lunch-${day.day}" data-lunch-day="${day.day}" aria-controls="lunch-times-${day.day}" ${day.lunch?'checked':''}>Intervalo de almoço<span class="sr-only"> de ${name}</span></label><div id="lunch-times-${day.day}" class="lunch-times" ${day.lunch?'':'hidden'}><label class="field">Início<input type="time" step="900" name="lunch-start-${day.day}" value="${esc(day.lunch?.start||'')}" aria-label="Início do almoço de ${name}" required ${day.lunch?'':'disabled'}></label><label class="field">Fim<input type="time" step="900" name="lunch-end-${day.day}" value="${esc(day.lunch?.end||'')}" aria-label="Fim do almoço de ${name}" required ${day.lunch?'':'disabled'}></label></div></div></div>`;}
const MAX_SERVICES=32;
function renderSettings(){const s=structuredClone(state.settings);document.getElementById('view-content').innerHTML=`<div class="page-title"><div><h1>Uma agenda do seu jeito.</h1><p>Defina o que você oferece e quando cada encontro pode acontecer.</p></div></div><div class="notice">${icon('clock')}<span>${state.settings.enabled?'As alterações valem para novos agendamentos. Reservas existentes não são alteradas; confira a agenda antes de definir o almoço.':'Os horários e durações abaixo são sugestões iniciais. Revise e salve antes de abrir a agenda.'}</span></div><form id="settings-form"><div class="settings-layout"><div><section class="panel"><div class="panel-header"><div><h2>Seus serviços</h2><p>Nome, duração e valor de cada cuidado.</p></div><button type="button" class="btn btn-secondary" id="add-service">${icon('plus')} Adicionar serviço</button></div><div class="settings-body"><p class="service-editor-help">Marque os serviços disponíveis para agendamento. Novos serviços só aparecem para as clientes depois de salvar. O valor padrão aparece no agendamento da cliente e preenche a conclusão do atendimento; você pode ajustá-lo ao receber. Sem valor definido, a cliente vê “Valor a combinar”.</p><p id="services-count" class="service-editor-count" role="status"></p><div id="services-list">${s.services.map((service,index)=>serviceSettingRow(service,index)).join('')}</div></div></section><section class="panel"><div class="panel-header"><div><h2>Dias e horários</h2><p>Defina o expediente e o almoço de cada dia.</p></div>${icon('calendar')}</div><div class="settings-body">${s.weekly.map(day=>daySettingRow(day)).join('')}</div></section></div><div class="settings-right"><section class="panel"><div class="panel-header"><div><h2>Agendamento online</h2><p>Você decide quando abrir sua agenda.</p></div>${icon('settings')}</div><div class="settings-body"><div class="toggle-box"><label class="checkbox-label"><input name="online-enabled" type="checkbox" ${s.enabled?'checked':''}>Ativar agendamento online</label><p>As clientes escolhem um horário e recebem a confirmação automaticamente.</p></div><label class="field">Antecedência mínima (minutos)<input name="lead-minutes" type="number" value="${s.leadMinutes}" min="0" max="2880" required><small>Tempo entre a reserva e o início do atendimento.</small></label><label class="field">Abrir agenda para os próximos (dias)<input name="advance-days" type="number" value="${s.advanceDays}" min="1" max="180" required></label><p class="muted" style="font-size:8px;line-height:1.9">Fuso horário: Salvador / Bahia.<br>Não há envio automático de mensagens ou cobrança nesta etapa.</p></div></section><section class="panel"><div class="panel-header"><div><h2>Uma pausa na agenda</h2><p>Bloqueie folgas ou intervalos específicos.</p></div>${icon('clock')}</div><div class="settings-body"><div id="block-fields"><label class="field">Data<input type="date" id="block-date" min="${state.today}"></label><label class="checkbox-label" style="margin-bottom:17px"><input id="block-all-day" type="checkbox" checked>Dia inteiro</label><div class="form-two" id="block-times" hidden><label class="field">De<input type="time" id="block-start" value="12:00" step="900"></label><label class="field">Até<input type="time" id="block-end" value="13:00" step="900"></label></div><label class="field">Observação (só para você)<input id="block-note" maxlength="150" placeholder="Ex.: folga, almoço, compromisso"></label><button type="button" class="btn btn-secondary" id="save-block">${icon('plus')} Bloquear horário</button></div><div class="blocks-list" id="blocks-list"></div></div></section></div></div><div class="settings-save"><button class="btn" type="submit" id="save-settings">Salvar configurações ${icon('check')}</button></div></form>`;
const servicesList=document.getElementById('services-list'),addService=document.getElementById('add-service');
function updateServiceCount(){const count=s.services.length;addService.disabled=count>=MAX_SERVICES;document.getElementById('services-count').textContent=count+' de '+MAX_SERVICES+' serviços cadastrados'+(count>=MAX_SERVICES?' — limite atingido.':'.');}
addService.onclick=()=>{if(s.services.length>=MAX_SERVICES)return;const service={id:'servico-'+crypto.randomUUID().replaceAll('-',''),name:'',description:'',duration:'',priceCents:null,active:true};s.services.push(service);servicesList.insertAdjacentHTML('beforeend',serviceSettingRow(service,s.services.length-1,true));updateServiceCount();servicesList.lastElementChild.querySelector('input[type=text]').focus();};
servicesList.addEventListener('click',event=>{if(!event.target.closest('.cancel-service-draft'))return;const row=event.target.closest('[data-service-id]');s.services=s.services.filter(service=>service.id!==row.dataset.serviceId);row.remove();updateServiceCount();addService.focus();});
servicesList.addEventListener('input',event=>{if(event.target.type!=='text'||!event.target.name.startsWith('service-name-'))return;const row=event.target.closest('[data-service-id]');row.querySelector('input[type=checkbox]').setAttribute('aria-label','Disponibilizar '+(event.target.value||'novo serviço')+' para agendamento');});
updateServiceCount();
root.querySelectorAll('[data-lunch-day]').forEach(toggle=>{toggle.onchange=()=>{const fields=document.getElementById('lunch-times-'+toggle.dataset.lunchDay);fields.hidden=!toggle.checked;fields.querySelectorAll('input').forEach(input=>input.disabled=!toggle.checked);if(toggle.checked)fields.querySelector('input').focus();};});
document.getElementById('settings-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget),button=document.getElementById('save-settings');const services=s.services.map(service=>{const price=String(form.get(`service-price-${service.id}`)||'').trim();return {...service,name:form.get(`service-name-${service.id}`),description:form.get(`service-description-${service.id}`),duration:Number(form.get(`service-duration-${service.id}`)),priceCents:price===''?null:moneyCents(price),active:form.has(`service-active-${service.id}`)};});const invalidPrice=services.find(service=>service.priceCents!==null&&(!Number.isSafeInteger(service.priceCents)||service.priceCents<0||service.priceCents>100000000));if(invalidPrice){notify('Informe um valor padrão válido de até R$ 1.000.000,00, com até duas casas decimais.',true);event.currentTarget.elements.namedItem(`service-price-${invalidPrice.id}`).focus();return;}const data={...s,enabled:form.has('online-enabled'),leadMinutes:Number(form.get('lead-minutes')),advanceDays:Number(form.get('advance-days')),services,weekly:s.weekly.map(day=>({...day,enabled:form.has(`day-enabled-${day.day}`),open:form.get(`day-open-${day.day}`),close:form.get(`day-close-${day.day}`),lunch:form.has(`day-lunch-${day.day}`)?{start:form.get(`lunch-start-${day.day}`),end:form.get(`lunch-end-${day.day}`)}:null}))};button.disabled=true;try{state.settings=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(data)});notify('Configurações salvas. '+(data.enabled?'Sua agenda online está ativa.':'A agenda online continua pausada.'));renderShell();}catch(error){notify(error.message,true);button.disabled=false;}};
document.getElementById('block-all-day').onchange=event=>document.getElementById('block-times').hidden=event.target.checked;
document.getElementById('save-block').onclick=async event=>{const data={date:document.getElementById('block-date').value,allDay:document.getElementById('block-all-day').checked,start:document.getElementById('block-start').value,end:document.getElementById('block-end').value,note:document.getElementById('block-note').value};if(!data.date)return notify('Escolha a data que deseja bloquear.',true);event.currentTarget.disabled=true;try{await api('/api/admin/blocks',{method:'POST',body:JSON.stringify(data)});state.blocks=(await api('/api/admin/blocks')).blocks;renderBlocks();notify('Pausa adicionada à agenda.');}catch(error){notify(error.message,true);}finally{document.getElementById('save-block').disabled=false;}};renderBlocks();}
function renderBlocks(){document.getElementById('blocks-list').innerHTML=state.blocks.length?state.blocks.map(block=>`<div class="block-row"><div><strong>${esc(dateLabel(block.date))} · ${block.start_minute===0&&block.end_minute===1440?'dia inteiro':`${minuteLabel(block.start_minute)} – ${minuteLabel(block.end_minute)}`}</strong><small>${esc(block.note||'Pausa na agenda')}</small></div><button type="button" class="icon-btn" data-remove-block="${block.id}" aria-label="Remover pausa de ${esc(dateLabel(block.date))}">${icon('close')}</button></div>`).join(''):'<p style="font-size:9px;color:var(--muted)">Nenhuma pausa cadastrada.</p>';root.querySelectorAll('[data-remove-block]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/api/admin/blocks/'+button.dataset.removeBlock,{method:'DELETE',body:'{}'});state.blocks=state.blocks.filter(b=>b.id!==button.dataset.removeBlock);renderBlocks();notify('Pausa removida.');}catch(error){notify(error.message,true);button.disabled=false;}});}
setInterval(async()=>{if(state.session?.admin&&['overview','agenda'].includes(state.view)&&!dialog.open&&document.visibilityState==='visible'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){try{const previous=state.birthdaysToday,view=state.view;await loadData();if(state.view!==view||!state.session?.admin||dialog.open)return;if(previous!==state.birthdaysToday)renderShell();else renderAgenda();}catch{ /* preserve the last loaded agenda during a temporary connection failure */ }}},30000);
start();
const birthdayLabel=(day,month)=>day&&birthdayMonths[month-1]?day+' de '+birthdayMonths[month-1].toLowerCase():'Não informado';
let directoryRequest=0;
async function renderDirectory(){
 const view=state.view,birthdays=view==='birthdays',sequence=++directoryRequest;
 const area=document.getElementById('view-content'),month=state.birthdayMonth??Number(state.today.slice(5,7));
 area.innerHTML=`<div class="page-title"><div><p class="label">RELACIONAMENTO COM CLIENTES</p><h1>${birthdays?'Aniversários':'Clientes'}</h1><p>${birthdays?'Veja as datas informadas e quem faz aniversário hoje.':'Consulte clientes da agenda e da loja, com o total líquido recebido em serviços e compras.'}</p></div></div>
 <section class="panel customer-directory"><form class="finance-period" id="directory-filter">${birthdays?`<label class="field">Mês<select name="month">${birthdayMonths.map((label,i)=>`<option value="${i+1}" ${month===i+1?'selected':''}>${label}</option>`).join('')}</select></label>`:`<label class="field">Buscar por nome ou celular<input name="q" type="search" maxlength="100" value="${esc(state.directoryQuery)}"></label>`}<button class="btn btn-secondary" type="submit">${birthdays?'Ver mês':'Buscar'}</button></form>
 <div id="directory-results" aria-live="polite"><p class="directory-message">Carregando…</p></div></section>`;
 const form=document.getElementById('directory-filter');
 const focus=()=>document.querySelector('#directory-filter .field :is(input, select)')?.focus();
 form.onsubmit=event=>{event.preventDefault();const values=new FormData(form);if(birthdays)state.birthdayMonth=Number(values.get('month'));else state.directoryQuery=String(values.get('q')||'');state.directoryOffset=0;renderDirectory();focus();};
 const params=new URLSearchParams({offset:state.directoryOffset,...(birthdays?{month}:{q:state.directoryQuery})});
 try{
  const data=await api('/api/admin/'+view+'?'+params);
  if(sequence!==directoryRequest||state.view!==view||!area.isConnected)return;
  const results=area.querySelector('#directory-results');
  const todayMonth=Number(data.today.slice(5,7)),todayDay=Number(data.today.slice(8));
  results.innerHTML=data.customers.length?`<ul class="directory-list">${data.customers.map(c=>{
   const isToday=c.birth_day===todayDay&&c.birth_month===todayMonth;
   return `<li class="directory-row ${birthdays?'directory-birthday':''} ${isToday?'directory-today':''}"><div class="client-cell"><span class="initial-avatar" aria-hidden="true">${esc(initials(c.name))}</span><div><strong>${esc(c.name)}</strong><small>${esc('+'+c.phone)}</small></div></div>
   <div><small>Aniversário</small><strong>${esc(birthdayLabel(c.birth_day,c.birth_month))}</strong>${isToday?'<span class="status confirmed">Hoje</span>':''}</div>
   ${birthdays?'':`<div><small>Total líquido recebido</small><strong>${moneyLabel(c.spentCents)}</strong>${c.unrecordedCount?'<small>Há atendimentos sem valor informado</small>':''}</div><div><small>Reservas e pedidos</small><strong>${c.bookingCount} reserva(s) · ${c.orderCount||0} pedido(s)</strong>${c.lastVisit?'<small>Último atendimento: '+esc(dateLabel(c.lastVisit))+'</small>':''}</div>`}</li>`;
  }).join('')}</ul>`:`<p class="directory-message">${birthdays?'Nenhum aniversário registrado neste mês.':'Nenhuma cliente encontrada.'}</p>`;
  if(data.total>data.limit||data.offset)results.insertAdjacentHTML('beforeend',`<div class="finance-pagination"><button class="btn btn-secondary" type="button" data-directory-page="-1" ${data.offset===0?'disabled':''}>Anterior</button><span>${data.offset+1}–${Math.min(data.offset+data.limit,data.total)} de ${data.total}</span><button class="btn btn-secondary" type="button" data-directory-page="1" ${data.offset+data.limit>=data.total?'disabled':''}>Próxima</button></div>`);
  results.querySelectorAll('[data-directory-page]').forEach(button=>button.onclick=()=>{state.directoryOffset+=Number(button.dataset.directoryPage)*data.limit;renderDirectory();focus();});
 }catch(error){if(sequence===directoryRequest&&state.view===view&&area.isConnected)area.querySelector('#directory-results').innerHTML='<p class="directory-message form-error">'+esc(error.message)+'</p>';}
}
function paymentOptions(value=''){return '<option value="">Escolha uma forma</option>'+Object.entries(paymentLabels).filter(([key])=>key!=='unrecorded').map(([key,label])=>`<option value="${key}" ${key===value?'selected':''}>${label}</option>`).join('');}
function renderCompletion(){const b=state.selected,price=state.settings.services.find(service=>service.id===b.service_id)?.priceCents;document.getElementById('booking-extra').innerHTML=`<form id="completion-form" class="reschedule-form"><h3>Concluir e registrar recebimento</h3><p>${price!=null?'O valor padrão atual do serviço já está preenchido. Ajuste se necessário e escolha a forma de pagamento.':'Este serviço ainda não tem valor padrão. Informe o total recebido e a forma de pagamento.'} A conclusão cria uma única entrada recebida no financeiro de hoje.</p><div class="form-two"><label class="field">Valor recebido (R$)<input name="amount" inputmode="decimal" value="${moneyInputValue(price)}" placeholder="0,00" maxlength="12" required><small>Use zero somente para uma cortesia.</small></label><label class="field">Forma de pagamento<select name="paymentMethod" required>${paymentOptions()}</select></label></div><button class="btn btn-success" type="submit">${icon('check')} Concluir e registrar entrada</button><p id="completion-error" class="form-error" role="alert"></p></form>`;document.getElementById('completion-form').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget),amountCents=moneyCents(data.get('amount'));if(!Number.isSafeInteger(amountCents)||amountCents<0||amountCents>100000000){document.getElementById('completion-error').textContent='Informe um valor válido com até duas casas decimais.';return;}mutateBooking({status:'completed',amountCents,paymentMethod:data.get('paymentMethod')});};document.querySelector('#completion-form input').focus();}
let financeRequest=0;
async function renderFinance(){const sequence=++financeRequest;if(!state.financeFrom){state.financeFrom=state.today.slice(0,7)+'-01';state.financeTo=addDays(addDays(state.financeFrom,32).slice(0,7)+'-01',-1);}const area=document.getElementById('view-content');area.innerHTML='<div class="boot-state"><span class="loader"></span><p>Carregando seu financeiro...</p></div>';try{const data=await api(`/api/admin/finance?from=${state.financeFrom}&to=${state.financeTo}&offset=${state.financeOffset}&source=${state.financeSource}`);if(sequence!==financeRequest||state.view!=='finance')return;state.finance=data;drawFinance();}catch(error){if(sequence!==financeRequest||state.view!=='finance')return;area.innerHTML=`<div class="empty-state"><h2>Não foi possível carregar o financeiro.</h2><p>${esc(error.message)}</p><button class="btn" id="retry-finance">Tentar novamente</button><button class="btn btn-secondary" id="reset-finance-period">Voltar ao mês atual</button></div>`;document.getElementById('retry-finance').onclick=renderFinance;document.getElementById('reset-finance-period').onclick=()=>{state.financeFrom='';state.financeOffset=0;renderFinance();};}}
function drawFinance(){const f=state.finance,s=f.summary;document.getElementById('view-content').innerHTML=`<div class="page-title"><div><p class="label">CONTROLE DO INSTITUTO</p><h1>Seu trabalho, em números.</h1><p>Entradas recebidas, saídas e saldo do período.</p></div><button class="btn" id="new-finance-entry">${icon('plus')} Novo lançamento</button></div><form class="finance-period" id="finance-period"><label class="field">De<input name="from" type="date" value="${f.from}" required></label><label class="field">Até<input name="to" type="date" value="${f.to}" required></label><label class="field">Origem<select name="source">${[['all','Tudo'],['services','Serviços'],['shop','Loja'],['manual','Lançamentos manuais']].map(([v,label])=>`<option value="${v}" ${f.source===v?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn btn-secondary" type="submit">Aplicar filtros</button></form><section class="metrics finance-metrics" aria-label="Resumo financeiro"><article class="metric"><div class="metric-head">Entradas recebidas ${icon('wallet')}</div><strong class="finance-income">${moneyLabel(s.incomeCents)}</strong><span>Serviços, produtos e outras entradas</span></article><article class="metric"><div class="metric-head">Saídas ${icon('arrow')}</div><strong class="finance-expense">${moneyLabel(s.expenseCents)}</strong><span>Despesas registradas no período</span></article><article class="metric"><div class="metric-head">Saldo do período ${icon('grid')}</div><strong>${moneyLabel(s.balanceCents)}</strong><span>Entradas menos saídas registradas</span></article></section><div class="notice">${icon('check')}<span>Atendimentos concluídos e recebimentos de pedidos aparecem aqui automaticamente. Use os filtros para consultar serviços, loja ou lançamentos manuais. Estornos de pedidos também entram no saldo.</span></div>${s.unpriced?`<div class="notice finance-warning">${icon('clock')}<span>${s.unpriced} serviço(s) antigo(s) sem valor informado. Edite o lançamento para completar os dados; eles ainda não entram nos totais.</span></div>`:''}<section class="panel" aria-label="Lançamentos financeiros"><div class="panel-header"><div><h2>Entradas e saídas</h2><p>${esc(dateLabel(f.from))} a ${esc(dateLabel(f.to))} · ${s.total} lançamento(s)</p></div>${icon('wallet')}</div>${f.entries.length?`<div class="table-wrap"><table class="finance-table"><thead><tr><th>Data</th><th>Descrição</th><th>Pagamento</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${f.entries.map(e=>`<tr class="${e.status==='void'?'finance-void':''}"><td>${esc(dateLabel(e.date,{day:'2-digit',month:'2-digit',year:'numeric'}))}</td><td><strong>${esc(e.description)}</strong><small>${esc(e.category)} · ${e.shop_entry_id?'Loja':e.booking_id?'Serviço concluído':'Manual'}${e.status==='void'?' · Anulado':''}</small></td><td>${esc(paymentLabels[e.payment_method]||'Não informado')}</td><td class="finance-value ${e.kind==='income'?'finance-income':'finance-expense'}">${e.amount_cents===null?'Valor a informar':(e.kind==='income'?'+ ':'− ')+moneyLabel(e.amount_cents)}</td><td><button class="icon-btn" data-finance-id="${e.id}" aria-label="Ver lançamento: ${esc(e.description)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div><div class="finance-pagination"><span>${f.offset+1}–${f.offset+f.entries.length} de ${s.total}</span><button class="btn btn-secondary" id="finance-prev" ${f.offset===0?'disabled':''}>Anterior</button><button class="btn btn-secondary" id="finance-next" ${f.offset+f.limit>=s.total?'disabled':''}>Próxima</button></div>`:`<div class="empty-state"><div class="empty-icon">${icon('wallet')}</div><h3>Ainda não há lançamentos neste período.</h3><p>Os serviços concluídos aparecem automaticamente. Você também pode registrar outras entradas e as despesas do instituto.</p><button class="btn btn-secondary" id="first-finance-entry">Registrar lançamento ${icon('plus')}</button></div>`}</section>`;
document.getElementById('new-finance-entry').onclick=()=>openFinanceEntry();document.getElementById('first-finance-entry')?.addEventListener('click',()=>openFinanceEntry());document.getElementById('finance-period').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget);state.financeFrom=String(data.get('from'));state.financeTo=String(data.get('to'));state.financeSource=String(data.get('source')||'all');state.financeOffset=0;renderFinance();};root.querySelectorAll('[data-finance-id]').forEach(button=>button.onclick=()=>openFinanceEntry(f.entries.find(e=>e.id===button.dataset.financeId)));document.getElementById('finance-prev')?.addEventListener('click',()=>{state.financeOffset=Math.max(0,f.offset-f.limit);renderFinance();});document.getElementById('finance-next')?.addEventListener('click',()=>{state.financeOffset=f.offset+f.limit;renderFinance();});}
function openFinanceEntry(entry=null){
 if(entry?.shop_entry_id){
  dialog.innerHTML=`<div class="dialog-top"><div><h2 id="dialog-title">Lançamento da loja</h2><p>FINANCEIRO INTEGRADO</p></div><button class="icon-btn" id="close-shop-finance" aria-label="Fechar lançamento">${icon('close')}</button></div><div class="dialog-body"><h3>${esc(entry.description)}</h3><p>${moneyLabel(entry.amount_cents)} · ${esc(paymentLabels[entry.payment_method]||'Outro')}</p><p class="finance-origin-note">Este lançamento acompanha o pedido. Consulte ou registre um estorno em Pedidos para manter o histórico consistente.</p><button class="btn" id="open-shop-orders">Abrir pedidos ${icon('arrow')}</button></div>`;
  document.getElementById('close-shop-finance').onclick=()=>dialog.close();document.getElementById('open-shop-orders').onclick=()=>{state.view='orders';history.replaceState(null,'','#orders');renderShell();};if(!dialog.open)dialog.showModal();return;
 }
 const linked=!!entry?.booking_id,voided=entry?.status==='void',key=crypto.randomUUID();dialog.innerHTML=`<div class="dialog-top"><div><h2 id="dialog-title">${entry?'Detalhes do lançamento':'Novo lançamento'}</h2><p>${linked?'ENTRADA DE SERVIÇO CONCLUÍDO':'CONTROLE FINANCEIRO'}</p></div><button class="icon-btn" id="close-finance" aria-label="Fechar lançamento">${icon('close')}</button></div><div class="dialog-body">${voided?`<div class="notice"><span>Lançamento anulado: ${esc(entry.void_reason)}. Ele não participa dos totais.</span></div>`:''}<form id="finance-entry-form"><div class="form-two"><label class="field">Tipo<select name="kind" ${linked?'disabled':''} ${voided?'disabled':''}><option value="income" ${entry?.kind!=='expense'?'selected':''}>Entrada recebida</option><option value="expense" ${entry?.kind==='expense'?'selected':''}>Saída</option></select></label><label class="field">Data do recebimento ou saída<input type="date" name="date" value="${entry?.date||state.today}" max="${state.today}" required ${voided?'disabled':''}></label></div><label class="field">Descrição<input name="description" minlength="3" maxlength="180" value="${esc(entry?.description||'')}" placeholder="Ex.: compra de produtos" required ${linked?'readonly':''} ${voided?'disabled':''}></label><label class="field">Categoria<input name="category" list="finance-categories" minlength="2" maxlength="60" value="${esc(entry?.category||'Outras entradas')}" required ${linked?'readonly':''} ${voided?'disabled':''}><datalist id="finance-categories"><option value="Produtos e materiais"><option value="Aluguel"><option value="Contas do instituto"><option value="Equipamentos"><option value="Outras despesas"><option value="Outras entradas"></datalist></label><div class="form-two"><label class="field">Valor (R$)<input name="amount" inputmode="decimal" maxlength="12" value="${entry?.amount_cents!=null?(entry.amount_cents/100).toFixed(2).replace('.',','):''}" placeholder="0,00" required ${voided?'disabled':''}>${linked?'<small>Zero é permitido para cortesia.</small>':''}</label><label class="field">Forma de pagamento<select name="paymentMethod" required ${voided?'disabled':''}>${paymentOptions(entry?.payment_method)}</select></label></div>${linked?'<p class="finance-origin-note">O vínculo com o atendimento é preservado. Você pode corrigir valor, data e forma de pagamento.</p>':''}<p id="finance-form-error" class="form-error" role="alert"></p>${!voided?`<div class="dialog-actions"><button type="submit" class="btn" id="save-finance">${icon('check')} Salvar lançamento</button>${entry&&!linked?'<button type="button" class="btn btn-danger" id="void-finance">Anular lançamento</button>':''}</div>`:''}</form><div id="finance-extra"></div></div>`;
document.getElementById('close-finance').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();const form=document.getElementById('finance-entry-form');form.elements.kind.onchange=()=>{if(!entry)form.elements.category.value=form.elements.kind.value==='expense'?'Outras despesas':'Outras entradas';};form.onsubmit=async event=>{event.preventDefault();const data=new FormData(form),amountCents=moneyCents(data.get('amount'));if(!Number.isSafeInteger(amountCents)||amountCents<(linked?0:1)||amountCents>100000000){document.getElementById('finance-form-error').textContent='Informe um valor válido com até duas casas decimais.';return;}const value={kind:linked?'income':data.get('kind'),date:data.get('date'),description:data.get('description'),category:data.get('category'),amountCents,paymentMethod:data.get('paymentMethod'),...(entry?{action:'edit',revision:entry.revision}:{idempotencyKey:key})};const buttons=dialog.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await api('/api/admin/finance'+(entry?'/'+entry.id:''),{method:entry?'PATCH':'POST',body:JSON.stringify(value)});dialog.close();await renderFinance();notify('Lançamento salvo.');}catch(error){document.getElementById('finance-form-error').textContent=error.message;buttons.forEach(b=>b.disabled=false);}};
document.getElementById('void-finance')?.addEventListener('click',()=>{document.getElementById('finance-extra').innerHTML='<form class="reschedule-form" id="void-finance-form"><p>A anulação retira este lançamento dos totais e mantém o histórico.</p><label class="field">Motivo da anulação<input name="reason" minlength="3" maxlength="180" required></label><button class="btn btn-danger" type="submit">Confirmar anulação</button><p id="void-finance-error" class="form-error" role="alert"></p></form>';document.getElementById('void-finance-form').onsubmit=async event=>{event.preventDefault();const reason=new FormData(event.currentTarget).get('reason');const buttons=dialog.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await api('/api/admin/finance/'+entry.id,{method:'PATCH',body:JSON.stringify({action:'void',revision:entry.revision,reason})});dialog.close();await renderFinance();notify('Lançamento anulado.');}catch(error){document.getElementById('void-finance-error').textContent=error.message;buttons.forEach(b=>b.disabled=false);}};});}
